// Quiz: w = week, q = question, o = options, a = index of correct option, why/trap = feedback, p = PDF page.
// Cards: w = week, t = name (front), f = LaTeX formula, or a list of lines (back), n = one-line meaning.
// In t and n, $...$ is inline math. Formulas are rendered by KaTeX in index.html.
const QUIZ = [], CARDS = [];
const T = String.raw; // keeps LaTeX backslashes as typed

// ── Week 1: reliability intro, data & descriptive stats, probability, conditional/Bayes ──
QUIZ.push(
  { w: 1, p: 32, q: 'In the bathtub curve, the early-life (burn-in / infant mortality) phase has which failure rate?',
    o: ['Increasing (IFR)', 'Decreasing (DFR)', 'Constant (CFR)', 'Zero'], a: 1,
    why: 'Early failures come from manufacturing defects; as weak units die off, the failure rate falls.',
    trap: 'Useful life = constant (CFR). Wear-out = increasing (IFR).' },
  { w: 1, p: 160, q: 'Failures during the normal operating (useful life) period are usually due to:',
    o: ['Poor quality control', 'Wearing of the system', 'Random/chance events', 'Design debugging'], a: 2,
    why: 'Useful life = chance failures: random loads, environment, human error, "acts of God".',
    trap: 'Poor QC is the early-life cause; wearing is the wear-out cause.' },
  { w: 1, p: 32, q: 'Which improvement action fits the WEAR-OUT phase of the bathtub curve?',
    o: ['Burn-in testing and screening', 'Preventive maintenance and parts replacement', 'Better QC and acceptance testing', 'Excess-strength redundancy only'], a: 1,
    why: 'Wear-out (fatigue, corrosion, ageing) is fought with derating, preventive maintenance, replacing parts, better material.',
    trap: 'Burn-in/screening/QC = early phase. Redundancy/robust design = useful-life phase.' },
  { w: 1, p: 16, q: 'The IEC definition of reliability rests on three key terms. Which set is correct?',
    o: ['Expected job, conditions of use, intended (mission) time', 'Cost, quality, warranty', 'Availability, maintainability, safety', 'Mean, variance, failure rate'], a: 0,
    why: 'Capability to perform its expected job, under specific conditions of use, over an intended period of time.' },
  { w: 1, p: 23, q: 'A system with HIGH maintainability has:',
    o: ['A high failure rate', 'A relatively low repair time', 'Availability always equal to 100%', 'No need for spare parts'], a: 1,
    why: 'Maintainability measures how easily something is repaired: high maintainability = short repair time.',
    trap: 'Availability = actual working time ÷ scheduled working time × 100% (a different idea).' },
  { w: 1, p: 162, q: 'As reliability increases, failure intensity:',
    o: ['Increases', 'Decreases', 'Has no effect', 'First increases then decreases'], a: 1,
    why: 'More reliable = fails less often, so failure intensity goes down.' },
  { w: 1, p: 156, q: 'Per the Week 1 tutorial (T1.1), which statement about reliability is TRUE?',
    o: ['The failure-rate-vs-time graph is called the reliability curve', 'Reliability is a non-functional requirement of a system', 'Identical systems under identical conditions always fail together', 'Early failures are not covered by warranty'], a: 1,
    why: 'Reliability is a non-functional requirement. The failure-rate-vs-time graph is the BATHTUB curve.',
    trap: 'Slide key also marks "reliability lies between 0 and 1, both exclusive" as TRUE.' },
  { w: 1, p: 57, q: 'A customer rating on a 1–5 scale is which type of variable?',
    o: ['Nominal', 'Ordinal', 'Continuous', 'Discrete only, never categorical'], a: 1,
    why: 'Categories with a natural order = ordinal.',
    trap: 'Zip code / exterior type = nominal (labels, no order). Bedrooms = discrete. Lot size = continuous.' },
  { w: 1, p: 166, q: 'Which graph represents the "five-point summary"?',
    o: ['Histogram', 'Bar chart', 'Box plot', 'Scatter plot'], a: 2,
    why: 'Box (and whisker) plot shows min, Q1, median, Q3, max.' },
  { w: 1, p: 64, q: 'A relative frequency distribution is often called:',
    o: ['A cumulative distribution', 'An observed (empirical) probability distribution', 'A sampling distribution', 'A joint distribution'], a: 1,
    why: 'Relative frequencies = chance of drawing an observation from each category in a random draw.' },
  { w: 1, p: 176, q: 'Drawing a red card OR drawing a club from a 52-card deck — these events are:',
    o: ['Independent', 'Dependent', 'Mutually exclusive', 'Exhaustive'], a: 2,
    why: 'A club is never red, so both cannot happen together: P(A∩B) = 0.',
    trap: 'Drawing cards one after another WITHOUT replacement = dependent; WITH replacement = independent.' },
  { w: 1, p: 249, q: 'For the theorem of total probability, the events B₁…B<sub>k</sub> must:',
    o: ['Be independent of A', 'Form a partition of the sample space', 'All have equal probability', 'Be null events'], a: 1,
    why: 'Partition = mutually exclusive and together exhaustive, each with P(Bᵢ) ≠ 0.' },
  { w: 1, p: 228, q: 'If A and B are independent, then P(B | A) equals:',
    o: ['P(A)', 'P(A∩B)', 'P(B)', '1 − P(B)'], a: 2,
    why: 'Knowing A happened tells you nothing about B, so P(B|A) = P(B).' },
  { w: 1, p: 138, q: 'You need the number of selections where ORDER DOES NOT MATTER. Use:',
    o: ['Permutation n!/(n−r)!', 'Combination n!/(r!(n−r)!)', 'n!/(n₁!n₂!…n<sub>k</sub>!)', 'Multiplication rule n₁n₂'], a: 1,
    why: 'Combination = order irrelevant (e.g. picking a team). Permutation = order matters (e.g. chair + treasurer).' },
);
CARDS.push(
  { w: 1, t: 'Classical probability', f: T`P(A) = \frac{m}{n}`, n: T`$m$ = favourable outcomes, $n$ = all equally likely outcomes.` },
  { w: 1, t: 'Complement rule', f: T`P(A^c) = 1 - P(A)`, n: T`Chance that A does NOT happen.` },
  { w: 1, t: 'Addition rule (union)', f: T`\begin{aligned} P(A \cup B) &= P(A) + P(B) \\ &\quad - P(A \cap B) \end{aligned}`, n: T`Mutually exclusive: $P(A \cap B) = 0$, so just add.` },
  { w: 1, t: 'Conditional probability', f: T`P(B \mid A) = \frac{P(A \cap B)}{P(A)}`, n: T`Chance of B given A has happened. Independent: $P(B \mid A) = P(B)$.` },
  { w: 1, t: 'Multiplication rule', f: T`P(A \cap B) = P(A)\,P(B \mid A)`, n: T`Independent: $P(A \cap B) = P(A)\,P(B)$.` },
  { w: 1, t: 'Theorem of total probability', f: T`P(A) = \sum_i P(A \mid B_i)\,P(B_i)`, n: T`The $B_i$ split the sample space into parts that do not overlap.` },
  { w: 1, t: "Bayes' theorem", f: [T`P(B_r \mid A) = \frac{P(A \mid B_r)\,P(B_r)}{P(A)}`, T`P(A) = \sum_i P(A \mid B_i)\,P(B_i)`], n: T`"Reverse" probability: which cause, given the effect.` },
  { w: 1, t: 'Permutation', f: T`{}^nP_r = \frac{n!}{(n-r)!}`, n: T`Order matters.` },
  { w: 1, t: 'Combination', f: T`{}^nC_r = \frac{n!}{r!\,(n-r)!}`, n: T`Order does not matter.` },
  { w: 1, t: 'Permutations with repeated kinds', f: T`\frac{n!}{n_1!\,n_2!\cdots n_k!}`, n: T`$n$ things: $n_1$ alike of one kind, $n_2$ alike of another, …` },
  { w: 1, t: 'Sample variance', f: T`s^2 = \frac{\sum (x_i - \bar{x})^2}{n-1}`, n: T`Divide by $n-1$, not $n$. Standard deviation $s = \sqrt{s^2}$.` },
  { w: 1, t: 'Availability', f: T`A = \frac{\text{working time}}{\text{scheduled time}}`, n: T`Actual working time over scheduled working time; × 100 for a percent. Chance the system is ready to use.` },
  { w: 1, t: 'Empirical reliability', f: T`R = 1 - \frac{N_f}{N}`, n: T`$N_f$ = number failed by time $t$, out of $N$ tested.` },
);

// ── Week 2: conditional-probability tutorial, random variables, discrete distributions ──
QUIZ.push(
  { w: 2, p: 12, q: 'A and B are MUTUALLY EXCLUSIVE (both with non-zero probability). Which relation is TRUE?',
    o: ['P(A|B) = P(A)', 'P(A∩B) = P(A)·P(B)', 'P(A|B)·P(B) = P(B|A)·P(A)', 'P(A∪B) = P(A)·P(B)'], a: 2,
    why: 'Both sides equal P(A∩B) (here 0), so the identity holds. The other two are independence rules.',
    trap: 'Mutually exclusive ≠ independent. If one happening rules the other out, they are actually dependent.' },
  { w: 2, p: 17, q: '"A and B are independent if and only if P(B|A) = P(B) or P(A|B) = P(A)." This statement is:',
    o: ['Correct', 'Incorrect — it needs both to hold separately', 'Correct only for mutually exclusive events', 'Correct only for continuous variables'], a: 0,
    why: 'Each condition is equivalent to P(A∩B) = P(A)P(B), so either one proves independence.' },
  { w: 2, p: 80, q: 'For a CONTINUOUS random variable, the probability of taking one exact value (e.g. height exactly 180 cm) is:',
    o: ['Equal to f(x) at that point', '0', '1 / number of values', 'Undefined'], a: 1,
    why: 'Probability is area under the pdf; a single point has zero width, so zero area.',
    trap: 'f(x) is a density, not a probability. Only intervals get probability.' },
  { w: 2, p: 81, q: 'For a continuous random variable X with pdf f(x), P(a < X < b) equals:',
    o: ['f(b) − f(a)', '∫ₐᵇ f(x) dx', 'Σ f(x) from a to b', 'F(a) − F(b)'], a: 1,
    why: 'Area under the density curve between a and b. (Equivalently F(b) − F(a), not F(a) − F(b).)' },
  { w: 2, p: 105, q: 'Var(a + bX), where a and b are constants, equals:',
    o: ['a + b·Var(X)', 'b·Var(X)', 'b²·Var(X)', 'a² + b²·Var(X)'], a: 2,
    why: 'Adding a constant shifts but does not spread; multiplying by b scales spread by b².',
    trap: 'For the MEAN: E(a + bX) = a + b·E(X) — there the a stays.' },
  { w: 2, p: 98, q: 'E(XY) = E(X)·E(Y) is guaranteed when:',
    o: ['X and Y are any random variables', 'X and Y are independent', 'X and Y are mutually exclusive', 'X and Y have equal means'], a: 1,
    why: 'Product rule needs independence. E(X + Y) = E(X) + E(Y) holds for ANY X, Y.' },
  { w: 2, p: 106, q: "Chebyshev's theorem says the probability of being within k standard deviations of the mean is:",
    o: ['Exactly 1 − 1/k²', 'At least 1 − 1/k², for any distribution', 'At most 1/k²', 'At least 1 − 1/k², only for normal data'], a: 1,
    why: 'It is a conservative lower bound that works for ANY distribution.',
    trap: 'k = 2 → at least 75%; k = 3 → at least ~89%. Not the normal 95%/99.7%.' },
  { w: 2, p: 129, q: 'Which is NOT a condition for a binomial experiment?',
    o: ['n identical trials', 'Two mutually exclusive outcomes per trial', 'Probability of success changes after every trial', 'Independent trials'], a: 2,
    why: 'p must stay CONSTANT across trials.' },
  { w: 2, p: 148, q: 'Sampling WITHOUT replacement from a finite lot, counting successes. The right distribution is:',
    o: ['Binomial', 'Hypergeometric', 'Poisson', 'Geometric'], a: 1,
    why: 'Without replacement the draws are not independent → hypergeometric.',
    trap: 'With replacement → binomial.' },
  { w: 2, p: 168, q: 'Negative binomial vs binomial: the negative binomial counts…',
    o: ['Number of successes in a fixed n trials', 'The trial number on which the k-th success occurs', 'Number of events per unit time', 'Number of failures before any success, in a fixed n'], a: 1,
    why: 'Negative binomial: keep going until k successes. Binomial: n is fixed, count successes.',
    trap: 'Geometric = negative binomial with k = 1 (trial of the FIRST success).' },
  { w: 2, p: 203, q: 'For a Poisson distribution with parameter λt:',
    o: ['Mean = λt, variance = √(λt)', 'Mean = variance = λt', 'Mean = λ, variance = t', 'Mean = λt, variance = λt(1 − λt)'], a: 1,
    why: 'Mean and variance are both λt — the Poisson signature.' },
  { w: 2, p: 181, q: 'Which is NOT a property of a Poisson process?',
    o: ['Counts in disjoint intervals are independent (memoryless)', 'P(one event in a tiny interval) ∝ interval length', 'P(more than one event in a tiny interval) is high', 'Applies to counts over time or a region of space'], a: 2,
    why: 'More than one event in a very short interval is NEGLIGIBLE.' },
  { w: 2, p: 145, q: 'The multinomial distribution is used when each trial has:',
    o: ['Exactly two outcomes', 'k possible outcomes (E₁…E<sub>k</sub>) with probabilities summing to 1', 'A continuous outcome', 'Outcomes drawn without replacement'], a: 1,
    why: 'Multinomial = binomial generalised to k outcome categories, n independent trials.' },
);
CARDS.push(
  { w: 2, t: 'Expected value E(X)', f: [T`E(X) = \sum x\,f(x)`, T`E(X) = \int x\,f(x)\,dx`], n: T`Sum if discrete, integral if continuous.` },
  { w: 2, t: 'Variance shortcut', f: T`\sigma^2 = E(X^2) - \mu^2`, n: T`Mean of the square minus the square of the mean.` },
  { w: 2, t: 'Linear rules for E and Var', f: [T`E(a + bX) = a + b\,E(X)`, T`\text{Var}(a + bX) = b^2\,\text{Var}(X)`], n: T`Adding $a$ moves the mean only. Independent: $\text{Var}(X \pm Y) = \text{Var}(X) + \text{Var}(Y)$, always plus.` },
  { w: 2, t: "Chebyshev's theorem", f: T`P(|X - \mu| < k\sigma) \ge 1 - \frac{1}{k^2}`, n: T`Same as $P(\mu - k\sigma < X < \mu + k\sigma)$. Any distribution: at least this much lies within $k$ SDs of the mean.` },
  { w: 2, t: 'Binomial', f: [T`f(x) = \binom{n}{x} p^x (1-p)^{n-x}`, T`\mu = np, \quad \sigma^2 = np(1-p)`], n: T`$x$ successes in $n$ independent trials, success chance $p$ each time.` },
  { w: 2, t: 'Hypergeometric', f: [T`f(x) = \frac{\binom{k}{x}\binom{N-k}{n-x}}{\binom{N}{n}}`, T`\mu = \frac{nk}{N}`], n: T`Draw $n$ without replacement from $N$ items, $k$ of which are successes.` },
  { w: 2, t: 'Negative binomial', f: T`b^*(x; k, p) = \binom{x-1}{k-1} p^k q^{x-k}`, n: T`Chance the $k$-th success comes on trial $x$. Here $q = 1 - p$.` },
  { w: 2, t: 'Geometric', f: T`g(x; p) = p\,q^{x-1}`, n: T`Chance the FIRST success comes on trial $x$. Here $q = 1 - p$.` },
  { w: 2, t: 'Poisson', f: [T`f(x) = \frac{e^{-\lambda t}(\lambda t)^x}{x!}`, T`\mu = \sigma^2 = \lambda t`], n: T`Number of events in time $t$ at rate $\lambda$. Mean = variance.` },
  { w: 2, t: 'Discrete uniform (1 to k)', f: [T`f(x) = \frac{1}{k}`, T`\mu = \frac{k+1}{2}, \quad \sigma^2 = \frac{k^2-1}{12}`], n: T`Values $1, 2, \dots, k$, all equally likely.` },
);

// ── Week 3: discrete tutorial, uniform/normal, gamma/exponential/lognormal/Weibull ──
